from fractions import Fraction as Q
import json

# Each curve is represented as sum(c_k * exp(k*s)); x and y are
# scaled by tau, and u by tau**2.
options = {
    1: (
        {1: Q(3), 0: Q(-3)},
        {-1: Q(1, 2), 0: Q(1, 2)},
        {-2: Q(1)},
        "x=3τ(e^s−1), y=τ(e^(−s)+1)/2, u=τ²e^(−2s)",
    ),
    2: (
        {1: Q(2), 0: Q(-2)},
        {2: Q(2), 0: Q(-1)},
        {0: Q(1, 2), -2: Q(1, 2)},
        "x=2τ(e^s−1), y=τ(2e^(2s)−1), u=τ²(1+e^(−2s))/2",
    ),
    3: (
        {1: Q(2), 0: Q(-2)},
        {1: Q(1, 2), 0: Q(1, 2)},
        {2: Q(1)},
        "x=2τ(e^s−1), y=τ(e^s+1)/2, u=τ²e^(2s)",
    ),
    4: (
        {-1: Q(1), 0: Q(-1)},
        {-1: Q(-2), 0: Q(3)},
        {-2: Q(2), 0: Q(-1)},
        "x=τ(e^(−s)−1), y=−2τ(e^(−s)−3/2), u=τ²(2e^(−2s)−1)",
    ),
}

def clean(a):
    return {k: v for k, v in a.items() if v}

def derivative(a):
    return clean({k - 1: k * v for k, v in a.items()})

def add(a, b):
    out = dict(a)
    for k, v in b.items():
        out[k] = out.get(k, Q(0)) + v
    return clean(out)

def scale(a, c):
    return clean({k: c * v for k, v in a.items()})

def multiply(a, b):
    out = {}
    for i, x in a.items():
        for j, y in b.items():
            out[i + j] = out.get(i + j, Q(0)) + x * y
    return clean(out)

def value_at_zero(a):
    return sum(a.values(), Q(0))

# Charpit for F=pq-u=0:
# x'=q, y'=p, p'=p, q'=q, u'=2u.
# Thus x''=x', y''=y', x'y'=u, and u'=2u.
survivors = []
for number, (x, y, u, _) in options.items():
    dx, dy, du = derivative(x), derivative(y), derivative(u)
    valid = (
        value_at_zero(x) == 0
        and value_at_zero(y) == 1
        and value_at_zero(u) == 1
        and derivative(dx) == dx
        and derivative(dy) == dy
        and multiply(dx, dy) == u
        and du == scale(u, Q(2))
        # Initial-curve compatibility gives p(0)=τ/2, q(0)=2τ.
        and value_at_zero(dy) == Q(1, 2)
        and value_at_zero(dx) == Q(2)
    )
    if valid:
        survivors.append(number)

if len(survivors) != 1:
    result = {"final_answer": "UNSUPPORTED", "evidence": {"survivors": survivors}}
else:
    n = survivors[0]
    result = {
        "final_answer": f"Option {n}: {options[n][3]}",
        "evidence": {
            "charpit_checks": "x''=x', y''=y', x'y'=u, u'=2u",
            "initial_data_and_slopes": "x(0)=0, y(0)=τ, u(0)=τ²; p(0)=τ/2, q(0)=2τ",
            "survivors": survivors,
        },
    }

print(json.dumps(result, separators=(",", ":")))
